from google.cloud import aiplatform

def get_vertex_ai_client(project_id: str, location: str):
    """Provides a configured Google Vertex AI client."""
    aiplatform.init(project=project_id, location=location)
    return aiplatform

def get_text_generation_model(model_id: str):
    """Returns a TextGenerationModel instance from Vertex AI."""
    return aiplatform.TextGenerationModel.from_pretrained(model_id)

import dataclasses

@dataclasses.dataclass
class PlatformPrompt:
    text: str

@dataclasses.dataclass
class PlatformOutput:
    text: str
    metadata: dict = dataclasses.field(default_factory=dict)

from google.cloud import translate_v2 as translate

def localized_platform_output(text_content: str, target_language: str):
    """Translates Google Vertex AI platform model output for another locale using Google Cloud Translation API."""
    translate_client = translate.Client()

    response = translate_client.translate(text_content, target_language=target_language)

    return {"original_text": text_content, "translated_text": response['translatedText'], "target_language": target_language}

from google.cloud import aiplatform

def platform_output_embedding(project_id: str, location: str, text_content: str):
    """Embeds Google Vertex AI platform outputs for evaluation or retrieval using Vertex AI Embedding API."""
    aiplatform.init(project=project_id, location=location)

    # Use the TextEmbeddingModel for generating embeddings
    model = aiplatform.TextEmbeddingModel.from_pretrained("textembedding-gecko")

    embeddings = model.get_embeddings([text_content])

    # The embeddings object contains a list of Embedding objects. We extract the values.
    if embeddings:
        return {"text": text_content, "embedding": embeddings[0].values}
    return {"text": text_content, "embedding": []}
